# Surah Saba (chapter 34) — part 2: ayat 11-20 (IDs 3617-3626)
SURAH = 34

ENTRIES = {
3617: (
"کہ وسیع زرہیں بناؤ اور باہم ملی چیزوں میں اندازہ کرو — اور نیک عمل کرو — بے شک میں تمہارے اعمال کو دیکھ رہا ہوں",
"""۱۔ داؤدؑ — زرہیں بنانا؛ حساب؛ نیک عمل؛ اللہ کی نگرانی۔
۲۔ ’’أَنِ اعْمَلْ سَابِغَاتٍ وَقَدِّرْ فِي السَّرْدِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ بَصِيرٌ‘‘ — کہ وسیع زرہیں بناؤ اور باہم ملی چیزوں میں اندازہ کرو — اور نیک عمل کرو — بے شک میں تمہارے اعمال کو دیکھ رہا ہوں — یعنی کہ وسیع زرہیں بناؤ اور باہم ملی چیزوں میں اندازہ کرو اور نیک عمل کرو بے شک میں تمہارے اعمال کو دیکھ رہا ہوں۔
۳۔ عملی سبق: صنعت و فن میں عمدگی کرو؛ نیک عمل کرو؛ اللہ کی نگرانی یاد رکھو۔"""
),
3618: (
"اور سلیمانؑ کے لیے ہوا — اس کی صبح ایک ماہ کی راہ اور اس کی شام ایک ماہ کی راہ — اور ہم نے اس کے لیے تانبے کا چشمہ بہا دیا — اور جن میں سے کچھ اس کے سامنے اس کے رب کے اذن سے کام کرتے تھے — اور جو ان میں سے ہمارے حکم سے برگشتہ ہوا ہم اسے دہکتی آگ کا عذاب چکھائیں گے",
"""۱۔ سلیمانؑ — ہوا کی سلطنت؛ تانبے کا چشمہ؛ جنات کی خدمت؛ نافرمان جنات کی سزا۔
۲۔ ’’وَلِسُلَيْمَانَ الرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ وَأَسَلْنَا لَهُ عَيْنَ الْقِطْرِ وَمِنَ الْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ السَّعِيرِ‘‘ — اور سلیمانؑ کے لیے ہوا — اس کی صبح ایک ماہ کی راہ اور اس کی شام ایک ماہ کی راہ — اور ہم نے اس کے لیے تانبے کا چشمہ بہا دیا — اور جن میں سے کچھ اس کے سامنے اس کے رب کے اذن سے کام کرتے تھے — اور جو ان میں سے ہمارے حکم سے برگشتہ ہوا ہم اسے دہکتی آگ کا عذاب چکھائیں گے — یعنی اور سلیمانؑ کے لیے ہوا اس کی صبح ایک ماہ کی راہ اور اس کی شام ایک ماہ کی راہ اور ہم نے اس کے لیے تانبے کا چشمہ بہا دیا اور جن میں سے کچھ اس کے سامنے اس کے رب کے اذن سے کام کرتے تھے اور جو ان میں سے ہمارے حکم سے برگشتہ ہوا ہم اسے دہکتی آگ کا عذاب چکھائیں گے۔
۳۔ عملی سبق: اللہ کی دی ہوئی حکومت پر شکر کرو؛ حکم سے سرتابی نہ کرو؛ اللہ سے ڈرو۔"""
),
3619: (
"وہ اس کے لیے وہ کچھ بناتے جس کی وہ خواہش کرے — محراب، مورتیاں، حوضوں جتنے بڑے پیالے اور رسیلی ہانڈیاں — اے آلِ داؤد شکریہ ادا کرو — اور میرے بندوں میں سے بہت کم شکر گزار ہیں",
"""۱۔ سلیمانؑ — محراب۔ مورتیاں۔ بڑے پیالے؛ ہانڈیاں؛ آلِ داؤد کا شکریہ؛ کم شاکرین۔
۲۔ ’’يَعْمَلُونَ لَهُ مَا يَشَاءُ مِن مَّحَارِيبَ وَتَمَاثِيلَ وَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَّاسِيَاتٍ اعْمَلُوا آلَ دَاوُودَ شُكْرًا وَقَلِيلٌ مِّنْ عِبَادِيَ الشَّكُورُ‘‘ — وہ اس کے لیے وہ کچھ بناتے جس کی وہ خواہش کرے — محراب، مورتیاں، حوضوں جتنے بڑے پیالے اور رسیلی ہانڈیاں — اے آلِ داؤد شکریہ ادا کرو — اور میرے بندوں میں سے بہت کم شکر گزار ہیں — یعنی وہ اس کے لیے وہ کچھ بناتے جس کی وہ خواہش کرے محراب مورتیاں حوضوں جتنے بڑے پیالے اور رسیلی ہانڈیاں اے آلِ داؤد شکریہ ادا کرو اور میرے بندوں میں سے بہت کم شکر گزار ہیں۔
۳۔ عملی سبق: اللہ کا شکر ادا کرو؛ فخرو تکبر سے بچو؛ اللہ سے ڈرو۔"""
),
3620: (
"پھر جب ہم نے اس پر موت کا فیصلہ کیا تو کسی نے انہیں اس کی موت پر آگاہ نہیں کیا سوائے زمین کی کیڑے کہ وہ اس کی چھڑی کھا رہا تھا — پھر جب وہ گر گیا تو جنات کو معلوم ہوا کہ اگر وہ غیب جانتے ہوتے تو وہ ذلت آمیز عذاب میں نہ رہتے",
"""۱۔ سلیمانؑ کی وفات — زمین کا کیڑا؛ چھڑی؛ جنات کا حقیقت سپما؛ غیب کا علم نہیں۔
۲۔ ’’فَلَمَّا قَضَيْنَا عَلَيْهِ الْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِ إِلَّا دَابَّۃُ الْأَرْضِ تَأْكُلُ مِنسَأَتَهُ فَلَمَّا خَرَّ تَبَيَّنَتِ الْجِنُّ أَن لَّوْ كَانُوا يَعْلَمُونَ الْغَيْبَ مَا لَبِثُوا فِي الْعَذَابِ الْمُهِينِ‘‘ — پھر جب ہم نے اس پر موت کا فیصلہ کیا تو کسی نے انہیں اس کی موت پر آگاہ نہیں کیا سوائے زمین کی کیڑے کہ وہ اس کی چھڑی کھا رہا تھا — پھر جب وہ گر گیا تو جنات کو معلوم ہوا کہ اگر وہ غیب جانتے ہوتے تو وہ ذلت آمیز عذاب میں نہ رہتے — یعنی پھر جب ہم نے اس پر موت کا فیصلہ کیا تو کسی نے انہیں اس کی موت پر آگاہ نہیں کیا سوائے زمین کی کیڑے کہ وہ اس کی چھڑی کھا رہا تھا پھر جب وہ گر گیا تو جنات کو معلوم ہوا کہ اگر وہ غیب جانتے ہوتے تو وہ ذلت آمیز عذاب میں نہ رہتے۔
۳۔ عملی سبق: موت کی حقیقت ذہن میں رکھو؛ تکبر نہ کرو؛ اللہ سے ڈرو۔"""
),
3621: (
"بے شک سبا والوں کے لیے ان کے مسکن میں ایک نشانی تھی — دو باغ دائیں اور بائیں — اپنے رب کے رزق سے کھاؤ اور اس کا شکر ادا کرو — پاکیزہ شہر اور بخشنے والا رب",
"""۱۔ اہلِ سبا — دو باغ؛ رزق؛ شکر؛ پاکیزہ شہر؛ غفور رب۔
۲۔ ’’لَقَدْ كَانَ لِسَبَإٍ فِي مَسْكَنِهِمْ آيَۃٌ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ كُلُوا مِن رِّزْقِ رَبِّكُمْ وَاشْكُرُوا لَهُ بَلْدَۃٌ طَيِّبَۃٌ وَرَبٌّ غَفُورٌ‘‘ — بے شک سبا والوں کے لیے ان کے مسکن میں ایک نشانی تھی — دو باغ دائیں اور بائیں — اپنے رب کے رزق سے کھاؤ اور اس کا شکر ادا کرو — پاکیزہ شہر اور بخشنے والا رب — یعنی بے شک سبا والوں کے لیے ان کے مسکن میں ایک نشانی تھی دو باغ دائیں اور بائیں اپنے رب کے رزق سے کھاؤ اور اس کا شکر ادا کرو پاکیزہ شہر اور بخشنے والا رب۔
۳۔ عملی سبق: رزقِ الٰہی پر شکر کرو؛ فرماں بردار بنو؛ اللہ سے ڈرو۔"""
),
3622: (
"پھر وہ منہ موڑ گئے تو ہم نے ان پر عَرِم کا سیلاب بھیج دیا — اور ان کے دو باغوں کے بدلے دو باغ دیے جن میں بدمزہ پھل اور جھاڑو اور تھوڑا بیری کا درخت تھا",
"""۱۔ سبا والوں کا عذاب — إعراض؛ سیل العرم؛ بدمزہ پھل؛ جھاڑو؛ تھوڑا بیری۔
۲۔ ’’فَأَعْرَضُوا فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ الْعَرِمِ وَبَدَّلْنَاهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَيْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَيْءٍ مِّن سِدْرٍ قَلِيلٍ‘‘ — پھر وہ منہ موڑ گئے تو ہم نے ان پر عَرِم کا سیلاب بھیج دیا — اور ان کے دو باغوں کے بدلے دو باغ دیے جن میں بدمزہ پھل اور جھاڑو اور تھوڑا بیری کا درخت تھا — یعنی پھر وہ منہ موڑ گئے تو ہم نے ان پر عَرِم کا سیلاب بھیج دیا اور ان کے دو باغوں کے بدلے دو باغ دیے جن میں بدمزہ پھل اور جھاڑو اور تھوڑا بیری کا درخت تھا۔
۳۔ عملی سبق: شکر چھوڑنے کا انجام دیکھو؛ اللہ سے ڈرو؛ نعمت کی قدر کرو۔"""
),
3623: (
"یہ ہم نے انہیں ان کے کفر کے بدلے بدلہ دیا — اور ہم صرف ناشکرے کو ہی بدلہ دیتے ہیں",
"""۱۔ بدلہ — کفر؛ ناشکروں کی جزا۔
۲۔ ’’ذَٰلِكَ جَزَيْنَاهُم بِمَا كَفَرُوا وَهَلْ نُجَازِي إِلَّا الْكَفُورَ‘‘ — یہ ہم نے انہیں ان کے کفر کے بدلے بدلہ دیا — اور ہم صرف ناشکرے کو ہی بدلہ دیتے ہیں — یعنی یہ ہم نے انہیں ان کے کفر کے بدلے بدلہ دیا اور ہم صرف ناشکرے کو ہی بدلہ دیتے ہیں۔
۳۔ عملی سبق: اللہ کا شکر کرو؛ ناشکری چھوڑو؛ اللہ سے ڈرو۔"""
),
3624: (
"اور ہم نے ان کے درمیان اور ان بستیوں کے درمیان جنہیں ہم نے برکت دی ہے ظاہر بستیاں بنائی — اور ان میں سفر کا اندازہ کیا — کہ ان میں راتوں اور دنوں میں امن سے چلو",
"""۱۔ سبا و برکت والی بستیوں — متصل بستیاں؛ تنظیم۔ سفر؛ امن۔
۲۔ ’’وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّتِي بَارَكْنَا فِيهَا قُرًى ظَاهِرَۃً وَقَدَّرْنَا فِيهَا السَّيْرَ سِيرُوا فِيهَا لَيَالِيَ وَأَيَّامًا آمِنِينَ‘‘ — اور ہم نے ان کے درمیان اور ان بستیوں کے درمیان جنہیں ہم نے برکت دی ہے ظاہر بستیاں بنائی — اور ان میں سفر کا اندازہ کیا — کہ ان میں راتوں اور دنوں میں امن سے چلو — یعنی اور ہم نے ان کے درمیان اور ان بستیوں کے درمیان جنہیں ہم نے برکت دی ہے ظاہر بستیاں بنائی اور ان میں سفر کا اندازہ کیا کہ ان میں راتوں اور دنوں میں امن سے چلو۔
۳۔ عملی سبق: اللہ کی برکت کو پہچانو؛ امن سے رہو؛ اللہ سے ڈرو۔"""
),
3625: (
"پھر انہوں نے کہا اے ہمارے رب ہمارے سفروں میں فاصلہ بڑھا دے — اور انہوں نے اپنے آپ پر ظلم کیا — تو ہم نے انہیں قصے بنا دیا اور انہیں بالکل ٹکڑے ٹکڑے کر دیا — بے شک اس میں ہر صابر و شاکر کے لیے نشانیاں ہیں",
"""۱۔ سبا والوں کی بددعا — سفروں میں فاصلہ؛ قصے بنا دیا جانا؛ نشانیاں برائے صابر و شاکر۔
۲۔ ’’فَقَالُوا رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوا أَنفُسَهُمْ فَجَعَلْنَاهُمْ أَحَادِيثَ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ‘‘ — پھر انہوں نے کہا اے ہمارے رب ہمارے سفروں میں فاصلہ بڑھا دے — اور انہوں نے اپنے آپ پر ظلم کیا — تو ہم نے انہیں قصے بنا دیا اور انہیں بالکل ٹکڑے ٹکڑے کر دیا — بے شک اس میں ہر صابر و شاکر کے لیے نشانیاں ہیں — یعنی پھر انہوں نے کہا اے ہمارے رب ہمارے سفروں میں فاصلہ بڑھا دے اور انہوں نے اپنے آپ پر ظلم کیا تو ہم نے انہیں قصے بنا دیا اور انہیں بالکل ٹکڑے ٹکڑے کر دیا بے شک اس میں ہر صابر و شاکر کے لیے نشانیاں ہیں۔
۳۔ عملی سبق: اللہ کی دی ہوئی صورت میں صبر کرو؛ شکر کرو؛ اللہ سے ڈرو۔"""
),
3626: (
"اور بے شک ابلیس نے ان پر اپنا گمان سچ ثابت کیا — تو انہوں نے اس کی پیروی کی سوائے مومنوں کی ایک جماعت کے",
"""۱۔ ابلیس کا گمان — سچ ثابت؛ مومنوں کی جماعت۔
۲۔ ’’وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ الْمُؤْمِنِينَ‘‘ — اور بے شک ابلیس نے ان پر اپنا گمان سچ ثابت کیا — تو انہوں نے اس کی پیروی کی سوائے مومنوں کی ایک جماعت کے — یعنی اور بے شک ابلیس نے ان پر اپنا گمان سچ ثابت کیا تو انہوں نے اس کی پیروی کی سوائے مومنوں کی ایک جماعت کے۔
۳۔ عملی سبق: شیطان کی پیروی سے بچو؛ ایمان پر ثابت رہو؛ اللہ سے ڈرو۔"""
),
}
